    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = b - a + 10</span> حيث <span dir=\"ltr\" class=\"expr\">A = 9 - (a + 4) - (-5) + b</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = b - a + 10</span> حيث <span dir=\"ltr\" class=\"expr\">B = b - a + 8</span> <span dir=\"ltr\" class=\"expr\">B = 8 - (a + 1) - (-1) + b</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = b - a + 10</span> حيث <span dir=\"ltr\" class=\"expr\">B = b - a + 8</span> <span dir=\"ltr\" class=\"expr\">C = b - a - 15</span> <span dir=\"ltr\" class=\"expr\">C = -7 - (8 - b + a)</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = b - a + 10</span> حيث <span dir=\"ltr\" class=\"expr\">B = b - a + 8</span> <span dir=\"ltr\" class=\"expr\">C = b - a - 15</span> <span dir=\"ltr\" class=\"expr\">D = -x - y - 1</span> <span dir=\"ltr\" class=\"expr\">D = (x + z) - x - [1 - (-x - y - z)]</span><br><span class=\"q\">5) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = b - a + 10</span> حيث <span dir=\"ltr\" class=\"expr\">B = b - a + 8</span> <span dir=\"ltr\" class=\"expr\">C = b - a - 15</span> <span dir=\"ltr\" class=\"expr\">D = -x - y - 1</span> <span dir=\"ltr\" class=\"expr\">E = 2</span> <span dir=\"ltr\" class=\"expr\">E = -2 - (x - 2) - [-4 - (x - 2)]</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين","math":"<span dir=\"ltr\" class=\"expr\">- (a + 4) - (-5) = -a - 4 + 5</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = 9 - a - 4 + 5 + b</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = b - a + (9 - 4 + 5)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">9 - 4 + 5 = 10</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = b - a + 10</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوسين","math":"<span dir=\"ltr\" class=\"expr\">- (a + 1) - (-1) = -a - 1 + 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = 8 - a - 1 + 1 + b</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = b - a + (8 - 1 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">8 - 1 + 1 = 8</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = b - a + 8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">- (8 - b + a) = -8 + b - a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">C = -7 - 8 + b - a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">C = b - a + (-7 - 8)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-7 - 8 = -15</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">C = b - a - 15</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">- (-x - y - z) = x + y + z</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [1 + x + y + z] = -1 - x - y - z</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">D = x + z - x - 1 - x - y - z</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = (x - x - x) - y + (z - z) - 1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">0 - 1 = -1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">D = -x - y - 1</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 2) = -x + 2</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [-4 - x + 2] = 4 + x - 2</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -2 - x + 2 + 4 + x - 2</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = (-x + x) + (-2 + 2 + 4 - 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 2 + 4 - 2 = 2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = 2</span>"}],
