    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين الداخليين","math":"<span dir=\"ltr\" class=\"expr\">(6 - x)</span> و <span dir=\"ltr\" class=\"expr\">(x - 6)</span> متقابلان"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [6 - 6 + x] = -6 + 6 - x</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [-1 - x + 6] = 1 + x - 6</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = x - 6 + 6 - x + 1 + x - 6</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (x - x + x) + (-6 + 6 + 1 - 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 + 6 + 1 - 6 = -5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 5</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = 5</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = 5 - 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 0</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 5</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) - 5 = -3</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = (-3) - (-5)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 2</span>"}],
