    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين الداخليين","math":"<span dir=\"ltr\" class=\"expr\">(3 - x)</span> و <span dir=\"ltr\" class=\"expr\">(x - 3)</span> متقابلان"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [1 - 3 + x] = -1 + 3 - x</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [-1 - x + 3] = 1 + x - 3</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = x - 1 + 3 - x + 1 + x - 3</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (x - x + x) + (-1 + 3 + 1 - 3)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 + 3 + 1 - 3 = 0</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) + 0 = -8</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = (-8) - 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -8</span>"}],
