    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين الداخليين","math":"<span dir=\"ltr\" class=\"expr\">(5 - x)</span> و <span dir=\"ltr\" class=\"expr\">(x - 5)</span> متقابلان"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [2 - 5 + x] = -2 + 5 - x</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [-4 - x + 5] = 4 + x - 5</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2 + 5 - x + 4 + x - 5</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (x - x + x) + (-2 + 5 + 4 - 5)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 5 + 4 - 5 = 2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x + 2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x + 2</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = 1 + 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x + 2</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) + 2 = 9</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = 9 - 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 7</span>"}],
