    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-12) - 5</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-12) - 5 = -17</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -17</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-12 - (-17) = 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = 1 + (-7)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 + (-7) = -6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -6</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">(-6) - (-7) = 1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">4 - x - (-3) = -4</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 - (-3) = 7</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">7 - x = -4</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 7 - (-4)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">7 - (-4) = 11</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 11</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4 - (11 + (-3)) = -4</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-12 + 7 - |x| = -2</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-12 + 7 = -5</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-5 - |x| = -2</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-5) - (-2)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-5) - (-2) = -3</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-3 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-10 + |x| - (-3) = -3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-10 - (-3) = -7</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-7 + |x| = -3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-3) - (-7)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) - (-7) = 4</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">4 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -4</span>"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-7 - 6 + |x| = -1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-7 - 6 = -13</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-13 + |x| = -1</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-1) - (-13)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-1) - (-13) = 12</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">12 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 12</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -12</span>"}],
