    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 9) = -b + 9</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 5) = a - 5</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-6 + c - 1) = 6 - c + 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -2 - b + 9 + a - 5 + 6 - c + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-2 + 9 - 5 + 6 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 9 - 5 + 6 + 1 = 9</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 9</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = (-7) - 3 - 5 + 9</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">(-7) - 3 - 5 + 9 = -6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = -6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-9 - |x| - 4 = -9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-9 - 4 = -13</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-13 - |x| = -9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-13) - (-9)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-13) - (-9) = -4</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-4 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
