    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 7) = -b + 7</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 4) = a - 4</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-3 + c - 2) = 3 - c + 2</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -2 - b + 7 + a - 4 + 3 - c + 2</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-2 + 7 - 4 + 3 + 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 7 - 4 + 3 + 2 = 6</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = 4 - (-5) - (-6) + 6</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">4 - (-5) - (-6) + 6 = 21</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 21</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 0 - 8</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">0 - 8 = -8</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-8 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
