    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث <span dir=\"ltr\" class=\"expr\">N = -4 + (-b + 6) - (-a + 2) - (-5 + c - 1)</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 7</span> و <span dir=\"ltr\" class=\"expr\">b = 5</span> و <span dir=\"ltr\" class=\"expr\">c = 2</span> <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span> حيث احسب <span dir=\"ltr\" class=\"expr\">N</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 7</span> و <span dir=\"ltr\" class=\"expr\">b = 5</span> و <span dir=\"ltr\" class=\"expr\">c = 2</span> جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-11 - (|x| + 6) = 7</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 6) = -b + 6</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 2) = a - 2</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-5 + c - 1) = 5 - c + 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -4 - b + 6 + a - 2 + 5 - c + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-4 + 6 - 2 + 5 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 6 - 2 + 5 + 1 = 6</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = 7 - 5 - 2 + 6</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">7 - 5 - 2 + 6 = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-11 - |x| - 6 = 7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-11 - 6 = -17</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-17 - |x| = 7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-17) - 7</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-17) - 7 = -24</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-24 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
