    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span> حيث <span dir=\"ltr\" class=\"expr\">B = -5 - [-(x - y + 1) + x - 8] - [2 + (y - x) + 4] + 1</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">11 + (x - (-3)) = 0</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-1 - (-7 - x) = -8</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">7 + |x| = 5</span><br><span class=\"q\">5) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">10 - |x| = 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">-(x - y + 1) = -x + y - 1</span>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [-x + y - 1 + x - 8] = -y + 1 + 8</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [2 + y - x + 4] = -2 - y + x - 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -5 - y + 1 + 8 - 2 - y + x - 4 + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = x + (-y - y) + (-5 + 1 + 8 - 2 - 4 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 + 1 + 8 - 2 - 4 + 1 = -1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - 2y - 1</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">11 + x - (-3) = 0</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">11 - (-3) = 14</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">14 + x = 0</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 0 - 14</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">0 - 14 = -14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -14</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">11 + ((-14) - (-3)) = 0</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-1 - (-7) + x = -8</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 - (-7) = 6</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">6 + x = -8</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-8) - 6</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-8) - 6 = -14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -14</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-1 - (-7 - (-14)) = -8</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 5 - 7</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">5 - 7 = -2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-2 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 10 - 4</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">10 - 4 = 6</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">6 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 6</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -6</span>"}],
