    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span> حيث <span dir=\"ltr\" class=\"expr\">B = -2 - [-(x - y + 2) + x - 1] - [4 + (y - x) + 3] + 1</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">9 - x = -8</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">10 - (x + 7) = 7</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-7 - (-2 - |x|) = -7</span><br><span class=\"q\">5) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span> حيث جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-4 + [2 - |x|] = -9</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">-(x - y + 2) = -x + y - 2</span>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [-x + y - 2 + x - 1] = -y + 2 + 1</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [4 + y - x + 3] = -4 - y + x - 3</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -2 - y + 2 + 1 - 4 - y + x - 3 + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = x + (-y - y) + (-2 + 2 + 1 - 4 - 3 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 2 + 1 - 4 - 3 + 1 = -5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - 2y - 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 9 - (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">9 - (-8) = 17</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 17</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">9 - 17 = -8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">10 - x - 7 = 7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">10 - 7 = 3</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">3 - x = 7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 3 - 7</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">3 - 7 = -4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -4</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">10 - ((-4) + 7) = 7</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-7 - (-2) + |x| = -7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-7 - (-2) = -5</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-5 + |x| = -7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-7) - (-5)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-7) - (-5) = -2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-2 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-4 + 2 - |x| = -9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 2 = -2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-2 - |x| = -9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-2) - (-9)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-2) - (-9) = 7</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">7 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 7</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -7</span>"}],
