    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نلاحظ المجموعة المتكرّرة","math":"<span dir=\"ltr\" class=\"expr\">(1 - a)</span> موجودة مرّتين بإشارتين متعاكستين"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">-[-7 - (1 - a)] = 7 + 1 - a</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(b - 12) + (1 - a)] = -b + 12 - 1 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">G = 7 + 1 - a - b + 12 - 1 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">G = (-a + a) + (1 - 1) - b + (7 + 12)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 + 1 + 12 - 1 = 19</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 19</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 19</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 19 = 13</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = 13 - 19</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب G","math":"<span dir=\"ltr\" class=\"expr\">G = -(-8) + 19 = 27</span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = |G|</span> لأنّ العددين المتقابلين لهما نفس القيمة المطلقة"},{"quoi":"نحسب القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = 27</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b + |-G| + 2 = (-8) + 27 + 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(-8) + 27 + 2 = 21</span>"}],
