    enonce: "<span class=\"q\">1) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 5</span> حيث <span dir=\"ltr\" class=\"expr\">A = -3 - |a + 2| + |a - 1| + |a| - (-8)</span><br><span class=\"q\">2) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 5</span> حيث بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = y + z + 1</span> <span dir=\"ltr\" class=\"expr\">B = -5 - [x - (z + y)] - [(-x + y - 4) + (-2 - y)]</span><br><span class=\"q\">3) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 5</span> حيث بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = y + z + 1</span> <span dir=\"ltr\" class=\"expr\">B</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 8</span> و <span dir=\"ltr\" class=\"expr\">z = 1</span> <span dir=\"ltr\" class=\"expr\">B = -5 - [x - (z + y)] - [(-x + y - 4) + (-2 - y)]</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = -3 - |5 + 2| + |5 - 1| + |5| + 8</span>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|5 + 2| = 7</span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|5 - 1| = 4</span>"},{"quoi":"القيمة المطلقة الثالثة","math":"<span dir=\"ltr\" class=\"expr\">|5| = 5</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">A = -3 - 7 + 4 + 5 + 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 7</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 4) + (-2 - y)] = x - y + 4 + 2 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -5 - x + z + y + x - y + 4 + 2 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-5 + 4 + 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 + 4 + 2 = 1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 1</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 8</span> و <span dir=\"ltr\" class=\"expr\">z = 1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = 8 + 1 + 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = 10</span>"}],
