    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = -5 - |-9 + 3| + |-9 - 9| + |-9| + 1</span>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|-9 + 3| = 6</span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|-9 - 9| = 18</span>"},{"quoi":"القيمة المطلقة الثالثة","math":"<span dir=\"ltr\" class=\"expr\">|-9| = 9</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">A = -5 - 6 + 18 + 9 + 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 17</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 2) + (-5 - y)] = x - y + 2 + 5 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -3 - x + z + y + x - y + 2 + 5 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-3 + 2 + 5)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-3 + 2 + 5 = 4</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 4</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 4</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 2</span> و <span dir=\"ltr\" class=\"expr\">z = 9</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = 2 + 9 + 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = 15</span>"}],
