    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-9 + x = -2</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">x - 5 = 3</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-9 + [7 - x] = 9</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">1 - x = -6</span><br><span class=\"q\">5) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">9 - (|x| + 2) = 9</span><br><span class=\"q\">6) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-8 + (|x| - (-4)) = 3</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-2) - (-9)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-2) - (-9) = 7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 7</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-9 + 7 = -2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = 3 + 5</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">3 + 5 = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 8</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">8 - 5 = 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-9 + 7 - x = 9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-9 + 7 = -2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-2 - x = 9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-2) - 9</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-2) - 9 = -11</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -11</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-9 + [7 - (-11)] = 9</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 1 - (-6)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 - (-6) = 7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 7</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">1 - 7 = -6</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">9 - |x| - 2 = 9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">9 - 2 = 7</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">7 - |x| = 9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 7 - 9</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">7 - 9 = -2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-2 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-8 + |x| - (-4) = 3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-8 - (-4) = -4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-4 + |x| = 3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 3 - (-4)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">3 - (-4) = 7</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">7 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 7</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -7</span>"}],
