    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">9 + (x - (-9)) = 3</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-6 - (x + (-4)) = 1</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">2 - x = 1</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">11 + [1 - x] = 8</span><br><span class=\"q\">5) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">4 - (-9 - |x|) = 5</span><br><span class=\"q\">6) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">|x| - 3 = 7</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">9 + x - (-9) = 3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">9 - (-9) = 18</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">18 + x = 3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 3 - 18</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">3 - 18 = -15</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -15</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">9 + ((-15) - (-9)) = 3</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-6 - x - (-4) = 1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 - (-4) = -2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-2 - x = 1</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-2) - 1</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-2) - 1 = -3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -3</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-6 - ((-3) + (-4)) = 1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 2 - 1</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">2 - 1 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">2 - 1 = 1</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">11 + 1 - x = 8</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">11 + 1 = 12</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">12 - x = 8</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 12 - 8</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">12 - 8 = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">11 + [1 - 4] = 8</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">4 - (-9) + |x| = 5</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 - (-9) = 13</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">13 + |x| = 5</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 5 - 13</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">5 - 13 = -8</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-8 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">|x| = 7 + 3</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">7 + 3 = 10</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">10 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 10</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -10</span>"}],
