    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">2 + (x - 4) = -3</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">6 - (x + (-8)) = -7</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">4 + [-8 - x] = -8</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">3 - x = -5</span><br><span class=\"q\">5) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-1 - (-9 - |x|) = -3</span><br><span class=\"q\">6) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">|x| - (-8) = 9</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">2 + x - 4 = -3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 - 4 = -2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-2 + x = -3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-3) - (-2)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) - (-2) = -1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -1</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">2 + ((-1) - 4) = -3</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">6 - x - (-8) = -7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">6 - (-8) = 14</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">14 - x = -7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 14 - (-7)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">14 - (-7) = 21</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 21</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">6 - (21 + (-8)) = -7</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">4 + -8 - x = -8</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 + (-8) = -4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-4 - x = -8</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-4) - (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - (-8) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4 + [-8 - 4] = -8</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 3 - (-5)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">3 - (-5) = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 8</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">3 - 8 = -5</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">-1 - (-9) + |x| = -3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 - (-9) = 8</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">8 + |x| = -3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-3) - 8</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-3) - 8 = -11</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-11 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">|x| = 9 + (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">9 + (-8) = 1</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">1 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 1</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -1</span>"}],
